import{_ as a}from"./chunks/topology.CyzDb5iP.js";import{_ as t,o,c as i,ao as r}from"./chunks/framework.CcAkc8ux.js";const m=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"HaloGrids.jl","text":"Halo exchange with explicit grids.","tagline":"Build Cartesian MPI topologies, wrap local arrays, and exchange boundary data in Julia.","actions":[{"theme":"brand","text":"Get started","link":"/guide/getting-started"},{"theme":"alt","text":"Explore the API","link":"/api"}]},"features":[{"title":"Explicit ownership","details":"Topologies own communicators. Grids own communication caches. Fields declare their halo widths."},{"title":"Two or three dimensions","details":"Exchange multiple fields across Cartesian process layouts with periodic or nonperiodic boundaries."},{"title":"Split-phase exchange","details":"Start an exchange, perform independent work, then finish the final dimension's communication."},{"title":"Per-field halos and overlaps","details":"Each field declares its own halo width and overlap, so staggered and padded arrays share one grid."},{"title":"Optional backends and I/O","details":"CUDA arrays (tested on hardware), AMDGPU arrays (untested), CellArrays, parallel HDF5-style checkpoints, and ParaView output load as extensions."},{"title":"Reductions and coordinates","details":"Global sums, extrema, and norms, plus global index and coordinate helpers for each field."}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}`),d={name:"index.md"};function s(n,e,l,c,h,p){return o(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="How-it-fits-together" tabindex="-1">How it fits together <a class="header-anchor" href="#How-it-fits-together" aria-label="Permalink to &quot;How it fits together {#How-it-fits-together}&quot;">​</a></h2><p>A <code>Topology</code> arranges MPI ranks on a Cartesian lattice. Each rank owns a local array whose outer cells are halos, filled from its neighbors by <code>update_halo!</code>.</p><p><img src="'+a+'" alt=""></p><p>Continue with <a href="./guide/concepts">Topologies, grids, and fields</a> for the model, <a href="./guide/halo-exchange">Halo exchange</a> for corners, face halos, and overlaps, or <a href="./guide/hide-communication">Hiding communication</a> for the split-phase API.</p><h2 id="Current-scope" tabindex="-1">Current scope <a class="header-anchor" href="#Current-scope" aria-label="Permalink to &quot;Current scope {#Current-scope}&quot;">​</a></h2><p>These pages describe the implementation in this checkout of version 0.1.0. The examples use CPU arrays. <code>CuArray</code>/<code>ROCArray</code> fields work as drop-in replacements wherever a <code>Field</code> wraps an array (see <code>ext/HaloGridsCUDAExt.jl</code> and <code>ext/HaloGridsAMDGPUExt.jl</code>); the CUDA extension is tested against real hardware, while the AMDGPU extension is a structurally identical port that has not been run against real ROCm hardware yet. <code>save_hdf5</code>/<code>load_hdf5!</code> (see <code>ext/HaloGridsHDF5Ext.jl</code> and the <a href="./guide/hdf5-io">MPI/HDF5 file I/O guide</a>) write and read <code>Field</code> data to/from a shared HDF5 file once <code>HDF5</code> is loaded; no parallel-HDF5 build is assumed, so ranks take turns writing rather than writing simultaneously — see the guide for what that does and doesn&#39;t change for the caller. <code>save_pvtk</code> (see <code>ext/HaloGridsWriteVTKExt.jl</code> and the <a href="./guide/pvtk-io">Parallel ParaView (pvtk) I/O guide</a>) writes <code>Field</code> data to ParaView&#39;s parallel VTK XML image-data format once <code>WriteVTK</code> is loaded; unlike <code>save_hdf5</code>, every rank writes its own independent file (no shared-file write coordination needed), but halo cells are written rather than trimmed, and periodic topologies are not yet supported.</p>',6)])])}const g=t(d,[["render",s]]);export{m as __pageData,g as default};
